using Kaminari.Seseragi.Lakehouse.Delta;
using Kaminari.Seseragi.Lakehouse.Delta.Actions;
using Kaminari.Seseragi.Lakehouse.Delta.Schema;
using Polars.NET.Core.Enums;
using Polars.NET.Core.Exceptions;
using Polars.NET.Core.Wrappers;

namespace Polars.NET.Core.Delta;

/// <summary>
/// Generating the values of identity columns (see <see cref="IdentityColumn"/>) as rows are written, by Spark's
/// rules: a GENERATED ALWAYS column takes no values from the data; a GENERATED BY DEFAULT column keeps the values the
/// data brings (null included) and is generated only when the data lacks the column; identity columns are never
/// updated. Generated values are consecutive steps after the high water mark (Spark leaves gaps between tasks).
/// </summary>
internal static class DeltaKernelIdentity
{
    private const string IndexColumn = "__seseragi_identity_index";

    /// <summary>
    /// The rows (consumed) with values for the identity columns they lack, numbered in the order the engine
    /// produces them; <paramref name="generated"/> are those columns.
    /// </summary>
    /// <param name="present">The columns the rows have.</param>
    /// <exception cref="PolarsException">The rows bring values for a GENERATED ALWAYS column.</exception>
    public static LazyFrameHandle Fill(
        LazyFrameHandle rows, IReadOnlyList<IdentityColumn> columns, StructType present, out List<IdentityColumn> generated)
    {
        generated = [];
        foreach (IdentityColumn column in columns)
        {
            if (present.Field(column.Name) is null) generated.Add(column);
            else if (!column.AllowExplicitInsert) throw ExplicitInsert(column.Name);
        }
        if (generated.Count == 0) return rows;

        LazyFrameHandle indexed = PolarsWrapper.LazyFrameWithRowIndex(rows, IndexColumn);
        ExprHandle[] exprs =
        [
            .. present.Fields.Select(f => PolarsWrapper.Col(f.Name)),
            .. generated.Select(c => PolarsWrapper.Alias(Value(c, PolarsWrapper.Col(IndexColumn)), c.Name)),
        ];
        return PolarsWrapper.LazySelect(indexed, exprs);
    }

    /// <summary>The value of the identity column for the row at <paramref name="ordinal"/> (0, 1, …) among those generated.</summary>
    public static ExprHandle Value(IdentityColumn column, ExprHandle ordinal)
    {
        using DataTypeHandle int64 = PolarsWrapper.NewPrimitiveType((int)PlDataType.Int64);
        ExprHandle position = PolarsWrapper.ExprCast(ordinal, PolarsWrapper.DataTypeExprFromDataType(int64), strict: true, wrapNumerical: false);
        return PolarsWrapper.Add(PolarsWrapper.Lit(column.NextValue), PolarsWrapper.Mul(PolarsWrapper.Lit(column.Step), position));
    }

    /// <summary>The high water marks after <paramref name="count"/> rows got generated values.</summary>
    /// <exception cref="PolarsException">The values ran beyond the range of a long.</exception>
    public static Dictionary<string, long> Marks(IEnumerable<IdentityColumn> generated, long count)
    {
        var marks = new Dictionary<string, long>(StringComparer.Ordinal);
        if (count == 0) return marks;
        try
        {
            foreach (IdentityColumn column in generated) marks[column.Name] = column.Advance(column.NextValue, count - 1);
        }
        catch (DeltaException e)
        {
            throw new PolarsException(e.Message, e);
        }
        return marks;
    }

    /// <summary>The rows the data files of <paramref name="adds"/> hold, from their statistics.</summary>
    public static long RowsOf(IEnumerable<AddAction> adds) =>
        adds.Sum(a => a.ParsedStats?.NumRecords ?? throw new PolarsException($"The file {a.Path} has no row count."));

    /// <summary>The metadata with new high water marks, or null when there are none to record (and no other change).</summary>
    public static MetadataAction? WithMarks(MetadataAction? changed, MetadataAction current, IReadOnlyDictionary<string, long> marks) =>
        marks.Count == 0 ? changed : IdentityColumns.WithHighWaterMarks(changed ?? current, marks);

    /// <summary>Spark's error for values given to a GENERATED ALWAYS column.</summary>
    public static PolarsException ExplicitInsert(string column) =>
        new($"Providing values for GENERATED ALWAYS AS IDENTITY column {column} is not supported.");

    /// <summary>Spark's error for changing an identity column's values.</summary>
    public static PolarsException UpdateNotSupported(string column) =>
        new($"UPDATE on IDENTITY column {column} is not supported.");
}
